  ('381f76fe-ee95-5564-b2ce-27d450833e5b', null, (select id from public.skills where slug = 'read-g11-theme-summary'), null, 'easy',
   $q$Which statement best expresses a central theme of the fable?$q$, $q$[{"text":"Even great expertise must be revised when the world it describes changes.","is_correct":true},{"text":"Rivers are unpredictable and impossible to map with any accuracy.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Young workers will always replace older ones in any trade.","is_correct":false,"misconception_token":"overgeneralization"},{"text":"Expensive products are always better than cheap ones.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$Even great expertise must be revised when the world it describes changes.$q$, $q$Orrin's skill is real, but his maps fail until he measures the new river, showing that knowledge must keep up with change. Liesl maps the river accurately, so it is not impossible to map.$q$, 'draft', 'bab7329c-41a8-5098-83e6-e160f484dcd1')
