  ('c6aea10c-4800-5d45-abef-90e17c4710d5', null, (select id from public.skills where slug = 'read-g11-theme-summary'), null, 'medium',
   $q$What does the observation that the clipboard "was where the day's news traveled" add to the theme?$q$, $q$[{"text":"It explains why Mr. Abernathy wants to remove the clipboard from the desk.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"It shows that the residents use the clipboard mainly to post newspaper articles.","is_correct":false,"misconception_token":"literal-reading"},{"text":"It suggests that the residents were gossiping instead of signing up for rides.","is_correct":false,"misconception_token":"misreads-tone"},{"text":"It shows that the clipboard served a social purpose the app ignored, so meeting needs means seeing how people live.","is_correct":true}]$q$::jsonb, $q$It shows that the clipboard served a social purpose the app ignored, so meeting needs means seeing how people live.$q$, $q$The clipboard is a gathering point where residents remind each other, which the app could not replace. "News" here means daily conversation, not newspaper articles.$q$, 'draft', 'f762e003-ca09-57c3-a8a2-d833a7afaabe')
