  ('4682a3f2-0e6f-578e-a5f2-53e60ab2b555', null, (select id from public.skills where slug = 'read-g11-theme-summary'), null, 'hard',
   $q$Why does Marisol pin the message next to screenshots of the unused app, and how does this develop the theme?$q$, $q$[{"text":"She wants to prove to visitors that the first app was better than the second.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"She plans to bring back the original app once the residents are ready for it.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"She is embarrassed by the first app and wants to hide it behind the message.","is_correct":false,"misconception_token":"misreads-detail"},{"text":"Keeping both reminds her that her success grew from her failure, linking ambition to the humility of listening.","is_correct":true}]$q$::jsonb, $q$Keeping both reminds her that her success grew from her failure, linking ambition to the humility of listening.$q$, $q$Placing the success beside the failure shows she values the lesson the unused app taught. The screenshots sit "next to" the message, not hidden behind it, and nothing suggests she plans to restore the app.$q$, 'draft', 'f762e003-ca09-57c3-a8a2-d833a7afaabe')
