  ('69a59f40-57a8-53eb-ad98-12b8a837b67c', null, (select id from public.skills where slug = 'read-g12-character-setting-plot'), null, 'medium',
   $q$How does the order of the objects in the first three stanzas shape the poem?$q$, $q$[{"text":"It widens from the speaker's childhood to the history of the whole neighborhood around the shop.","is_correct":false,"misconception_token":"misreads-sequence"},{"text":"It moves from the most valuable object to the least valuable one, showing what the speaker will sell.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It follows the order in which the grandfather bought the objects when he opened the shop.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It narrows from the shop's general workings to a memory of the speaker, preparing the personal final act.","is_correct":true}]$q$::jsonb, $q$It narrows from the shop's general workings to a memory of the speaker, preparing the personal final act.$q$, $q$The spools concern customers, the tape measure concerns the grandfather, and the chalk recalls the speaker's own recital dress, so the poem moves closer to the speaker's bond with him. No purchase order or value ranking is given.$q$, 'draft', '2197d1eb-c5c8-5df6-85e4-fdbb2eed36e9')
