  ('be6a14de-ba17-5055-920c-5cbd8350d286', null, (select id from public.skills where slug = 'read-g12-connections'), null, 'hard',
   $q$How is Duvall's chart related to Lindqvist's?$q$, $q$[{"text":"It replaced his chart entirely because factories had found his eight sizes too inaccurate for men.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It filled a gap his chart left, using his method of measuring many people on a group he had excluded.","is_correct":true},{"text":"It was created at the army's request so that women serving as nurses could wear uniforms.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It copied his measurements but divided them into more sizes so tailors could do fewer alterations.","is_correct":false,"misconception_token":"misreads-relationship"}]$q$::jsonb, $q$It filled a gap his chart left, using his method of measuring many people on a group he had excluded.$q$, $q$Lindqvist's chart came from recording many recruits; Duvall did the same with "the women who came to her shop," a group his chart fit poorly. She measured new people rather than copying his records.$q$, 'draft', '808ede3a-4c5b-588c-9124-0ef5b93698a5')
